// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";

import {
  isSparqlTerm,
  sparqlFacetValueToken,
  sparqlNodeId,
  sparqlTermFromNodeId,
} from "../../../main/frontend/graph-explorer/rdf-terms.ts";

test("malformed endpoint bindings are rejected before graph identity work", () => {
  assert.equal(isSparqlTerm({ type: "uri", value: 42 }), false);
  assert.equal(isSparqlTerm({ type: "not-a-term", value: "x" }), false);
  assert.equal(
    isSparqlTerm({ type: "literal", value: "x", datatype: 42 }),
    false,
  );
  assert.equal(
    isSparqlTerm({ type: "literal", value: "x", "xml:lang": "en" }),
    true,
  );
  assert.equal(
    isSparqlTerm({
      type: "literal",
      value: "x",
      "xml:lang": 'en" . FILTER(false) #',
    }),
    false,
  );
  assert.equal(
    isSparqlTerm({
      type: "literal",
      value: "x",
      datatype: "http://www.w3.org/2001/XMLSchema#string",
      "xml:lang": "en",
    }),
    false,
  );
  assert.equal(
    isSparqlTerm({ type: "bnode", value: "b0", datatype: "urn:bad" }),
    false,
  );
  assert.equal(isSparqlTerm({ type: "typed-literal", value: "x" }), false);
  assert.equal(
    isSparqlTerm({
      type: "typed-literal",
      value: "x",
      datatype: "urn:bad> . FILTER(false) #",
    }),
    false,
  );
});

test("RDF term identity keeps lexical collisions separate", () => {
  const iri = { type: "uri", value: "urn:example:same" };
  const plain = { type: "literal", value: "urn:example:same" };
  const typed = {
    type: "typed-literal",
    value: "urn:example:same",
    datatype: "http://www.w3.org/2001/XMLSchema#string",
  };
  const language = {
    type: "literal",
    value: "urn:example:same",
    "xml:lang": "EN",
  };

  const ids = [iri, plain, typed, language].map(sparqlNodeId);
  assert.equal(new Set(ids).size, ids.length);
  assert.equal(sparqlTermFromNodeId(ids[0])?.type, "uri");
  assert.equal(sparqlTermFromNodeId(ids[1])?.value, plain.value);
  assert.equal(sparqlTermFromNodeId(ids[2])?.datatype, typed.datatype);
  assert.equal(sparqlTermFromNodeId(ids[3])?.["xml:lang"], "en");
});

test("canonical facet tokens round-trip IRIs and literals safely", () => {
  const iriId = sparqlNodeId({ type: "uri", value: "urn:example:value" });
  const literalId = sparqlNodeId({
    type: "literal",
    value: 'quote "line\n',
    "xml:lang": "nb",
  });

  assert.equal(sparqlFacetValueToken(iriId), "<urn:example:value>");
  assert.equal(
    sparqlFacetValueToken(literalId),
    '"quote \\\"line\\n"@nb',
  );
});

test("blank-node facet values are not sent across endpoint requests", () => {
  const blankId = sparqlNodeId({ type: "bnode", value: "b0" });
  assert.equal(sparqlFacetValueToken(blankId), null);
});

test("malformed serialized literal IDs are rejected during round-trip parsing", () => {
  const prefix = "__rdf_literal__:";
  assert.equal(
    sparqlTermFromNodeId(`${prefix}${JSON.stringify({ type: "typed-literal", value: "5" })}`),
    undefined,
  );
  assert.equal(
    sparqlTermFromNodeId(
      `${prefix}${JSON.stringify({
        type: "literal",
        value: "hello",
        datatype: "urn:datatype",
        language: "en",
      })}`,
    ),
    undefined,
  );
});

test("language literals have one canonical identity even when endpoints include rdf:langString", () => {
  const withDatatype = sparqlNodeId({
    type: "literal",
    value: "hei",
    datatype: "http://www.w3.org/1999/02/22-rdf-syntax-ns#langString",
    "xml:lang": "NB",
  });
  const withoutDatatype = sparqlNodeId({
    type: "literal",
    value: "hei",
    "xml:lang": "nb",
  });
  assert.equal(withDatatype, withoutDatatype);
  assert.deepEqual(sparqlTermFromNodeId(withDatatype), {
    type: "literal",
    value: "hei",
    "xml:lang": "nb",
  });
});
